class PaymentCredentials(ABC):
    @abstractmethod
    def get_credentials(self):
        pass

class CreditCardCredentials(PaymentCredentials):
    def __init__(self, security_code: str):
        self.security_code = security_code

    def get_credentials(self):
        return f'Security Code: {self.security_code}'

class PaymentProcessor(ABC):
    @abstractmethod
    def pay(self, order, credentials: PaymentCredentials):
        pass

class CreditCardPaymentProcessor(PaymentProcessor):
    def pay(self, order, credentials: PaymentCredentials):
        print("Processing credit card payment")
        print(f"Verifying credentials: {credentials.get_credentials()}")
        order.status = "paid"

